Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ---------------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------------
$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Definition
$sourceDir = Join-Path $scriptDir "source"
$assetsDir = Join-Path $scriptDir "assets"
$dataDir   = Join-Path (Split-Path -Parent $scriptDir) "Data\prog\win\bin"

# Read whitepath.txt (generated by Nova Chrysalia alongside Setup.bat)
# Contains the path to the game's alba_data root directory.
$gameBinDir = $null
$whitePathFile = Join-Path $scriptDir "whitepath.txt"
if ([System.IO.File]::Exists($whitePathFile)) {
    $whitePath = (Get-Content $whitePathFile -Raw).Trim()
    if ($whitePath) {
        $gameBinDir = [System.IO.Path]::Combine($whitePath, "prog\win\bin")
    }
}

# ---------------------------------------------------------------------------
# Theme
# ---------------------------------------------------------------------------
$clrBg      = [System.Drawing.Color]::FromArgb(18, 18, 28)
$clrPanel   = [System.Drawing.Color]::FromArgb(28, 28, 42)
$clrAccent  = [System.Drawing.Color]::FromArgb(190, 150, 60)
$clrText    = [System.Drawing.Color]::White
$clrSub     = [System.Drawing.Color]::FromArgb(170, 170, 195)
$clrBtn     = [System.Drawing.Color]::FromArgb(48, 48, 68)
$fntTitle   = New-Object System.Drawing.Font("Segoe UI", 13, [System.Drawing.FontStyle]::Bold)
$fntHdr     = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
$fntBody    = New-Object System.Drawing.Font("Segoe UI",  9)
$fntSmall   = New-Object System.Drawing.Font("Segoe UI",  8)

# ---------------------------------------------------------------------------
# Choices
# ---------------------------------------------------------------------------
$choices = [ordered]@{
    Artwork     = "standard"
    Language    = "latin"
    DofGameplay = "keep"
    DofCutscene = "keep"
}

# ---------------------------------------------------------------------------
# Step definitions
# ---------------------------------------------------------------------------
$steps = @(
    [ordered]@{
        Key  = "Artwork"
        Title = "Artwork Style"
        Desc  = "Choose how character artworks and illustrations are displayed in the main menu."
        Opts  = @(
            [ordered]@{ Val = "standard"; Label = "Standard";  Detail = "Original desaturated look." }
            [ordered]@{ Val = "colorful"; Label = "Colorful";  Detail = "Restored colors." }
        )
        Imgs  = @("artwork_standard.png", "artwork_colorful.png")
    }
    [ordered]@{
        Key  = "Language"
        Title = "Language"
        Desc  = "Select which language fonts to use for menus and subtitles."
        Opts  = @(
            [ordered]@{ Val = "latin";   Label = "Latin + Japanese"; Detail = "English, French, German, Italian, Spanish, and Japanese." }
            [ordered]@{ Val = "chinese"; Label = "Chinese";          Detail = "Simplified Chinese HD font replacement." }
            [ordered]@{ Val = "korean";  Label = "Korean";           Detail = "Korean HD font replacement." }
        )
        Imgs  = $null
    }
    [ordered]@{
        Key  = "DofGameplay"
        Title = "Depth of Field - Gameplay"
        Desc  = "Controls the blur effect applied to background elements during exploration and combat."
        Opts  = @(
            [ordered]@{ Val = "keep";    Label = "Keep HD Depth of Field"; Detail = "Improved circular bokeh DoF, replacing the original low-quality blur." }
            [ordered]@{ Val = "disable"; Label = "Disable";                Detail = "No blur during exploration or combat." }
        )
        Imgs  = @("dof_gameplay_on.png", "dof_gameplay_off.png")
    }
    [ordered]@{
        Key  = "DofCutscene"
        Title = "Depth of Field - Cutscenes"
        Desc  = "Controls the blur effect during story cutscenes and map cinematics."
        Opts  = @(
            [ordered]@{ Val = "keep";    Label = "Keep HD Depth of Field"; Detail = "Improved DoF during cutscenes." }
            [ordered]@{ Val = "disable"; Label = "Disable";                Detail = "No blur during cutscenes." }
        )
        Imgs  = @("dof_cutscene_on.png", "dof_cutscene_off.png")
    }
)

# ---------------------------------------------------------------------------
# Helper: load image from assets\ (returns $null silently if missing)
# ---------------------------------------------------------------------------
function Load-Asset($filename) {
    if (-not $filename) { return $null }
    $p = Join-Path $assetsDir $filename
    if ([System.IO.File]::Exists($p)) {
        try { return [System.Drawing.Image]::FromFile($p) } catch {}
    }
    return $null
}

# ---------------------------------------------------------------------------
# Build form
# ---------------------------------------------------------------------------
$form = New-Object System.Windows.Forms.Form
$form.Text            = "FF XIII-2 HD Mod - Installation"
$form.ClientSize      = New-Object System.Drawing.Size(720, 480)
$form.StartPosition   = "CenterScreen"
$form.FormBorderStyle = "FixedDialog"
$form.MaximizeBox     = $false
$form.MinimizeBox     = $false
$form.BackColor       = $clrBg

# Header
$pnlHeader = New-Object System.Windows.Forms.Panel
$pnlHeader.SetBounds(0, 0, 720, 56)
$pnlHeader.BackColor = $clrPanel
$form.Controls.Add($pnlHeader)

$lblTitle = New-Object System.Windows.Forms.Label
$lblTitle.SetBounds(20, 10, 540, 36)
$lblTitle.Text      = "FF XIII-2  HD Font & GUI Mod"
$lblTitle.Font      = $fntTitle
$lblTitle.ForeColor = $clrAccent
$lblTitle.BackColor = [System.Drawing.Color]::Transparent
$pnlHeader.Controls.Add($lblTitle)

$lblStepNum = New-Object System.Windows.Forms.Label
$lblStepNum.SetBounds(580, 19, 120, 18)
$lblStepNum.Font      = $fntSmall
$lblStepNum.ForeColor = $clrSub
$lblStepNum.BackColor = [System.Drawing.Color]::Transparent
$lblStepNum.TextAlign = "MiddleRight"
$pnlHeader.Controls.Add($lblStepNum)

# Left content panel
$pnlLeft = New-Object System.Windows.Forms.Panel
$pnlLeft.SetBounds(0, 56, 440, 374)
$pnlLeft.BackColor = $clrBg
$form.Controls.Add($pnlLeft)

$lblStepTitle = New-Object System.Windows.Forms.Label
$lblStepTitle.SetBounds(24, 24, 400, 28)
$lblStepTitle.Font      = $fntHdr
$lblStepTitle.ForeColor = $clrText
$lblStepTitle.BackColor = [System.Drawing.Color]::Transparent
$pnlLeft.Controls.Add($lblStepTitle)

$lblStepDesc = New-Object System.Windows.Forms.Label
$lblStepDesc.SetBounds(24, 56, 400, 44)
$lblStepDesc.Font      = $fntBody
$lblStepDesc.ForeColor = $clrSub
$lblStepDesc.BackColor = [System.Drawing.Color]::Transparent
$pnlLeft.Controls.Add($lblStepDesc)

$pnlRadios = New-Object System.Windows.Forms.Panel
$pnlRadios.SetBounds(20, 108, 412, 256)
$pnlRadios.BackColor = [System.Drawing.Color]::Transparent
$pnlLeft.Controls.Add($pnlRadios)

# Right preview panel
$pnlRight = New-Object System.Windows.Forms.Panel
$pnlRight.SetBounds(440, 56, 280, 374)
$pnlRight.BackColor = $clrPanel
$form.Controls.Add($pnlRight)

$pic = New-Object System.Windows.Forms.PictureBox
$pic.SetBounds(10, 10, 260, 354)
$pic.SizeMode  = "Zoom"
$pic.BackColor = $clrPanel
$pic.Visible   = $false
$pnlRight.Controls.Add($pic)

$lblNoPic = New-Object System.Windows.Forms.Label
$lblNoPic.SetBounds(10, 160, 260, 40)
$lblNoPic.Text      = "No preview available"
$lblNoPic.Font      = $fntSmall
$lblNoPic.ForeColor = $clrSub
$lblNoPic.BackColor = [System.Drawing.Color]::Transparent
$lblNoPic.TextAlign = "MiddleCenter"
$pnlRight.Controls.Add($lblNoPic)

# Confirmation panel
$pnlConfirm = New-Object System.Windows.Forms.Panel
$pnlConfirm.SetBounds(0, 56, 720, 374)
$pnlConfirm.BackColor = $clrBg
$pnlConfirm.Visible   = $false
$form.Controls.Add($pnlConfirm)

$lblConfirmHdr = New-Object System.Windows.Forms.Label
$lblConfirmHdr.SetBounds(24, 24, 680, 28)
$lblConfirmHdr.Text      = "Review your choices"
$lblConfirmHdr.Font      = $fntHdr
$lblConfirmHdr.ForeColor = $clrText
$lblConfirmHdr.BackColor = [System.Drawing.Color]::Transparent
$pnlConfirm.Controls.Add($lblConfirmHdr)

$lblConfirmBody = New-Object System.Windows.Forms.Label
$lblConfirmBody.SetBounds(24, 64, 680, 290)
$lblConfirmBody.Font      = $fntBody
$lblConfirmBody.ForeColor = $clrSub
$lblConfirmBody.BackColor = [System.Drawing.Color]::Transparent
$pnlConfirm.Controls.Add($lblConfirmBody)

# Footer
$pnlFooter = New-Object System.Windows.Forms.Panel
$pnlFooter.SetBounds(0, 430, 720, 50)
$pnlFooter.BackColor = $clrPanel
$form.Controls.Add($pnlFooter)

function New-WizBtn($text, $x) {
    $b = New-Object System.Windows.Forms.Button
    $b.SetBounds($x, 10, 100, 30)
    $b.Text      = $text
    $b.FlatStyle = "Flat"
    $b.FlatAppearance.BorderColor = $clrAccent
    $b.FlatAppearance.BorderSize  = 1
    $b.BackColor = $clrBtn
    $b.ForeColor = $clrText
    $b.Font      = $fntBody
    $b.Cursor    = "Hand"
    $pnlFooter.Controls.Add($b)
    return $b
}

$btnBack    = New-WizBtn "< Back"  10
$btnNext    = New-WizBtn "Next >"  610
$btnInstall = New-WizBtn "Install" 610
$btnInstall.Visible   = $false
$btnInstall.BackColor = [System.Drawing.Color]::FromArgb(90, 70, 15)

$dots = @()
for ($i = 0; $i -lt 5; $i++) {
    $d = New-Object System.Windows.Forms.Panel
    $d.Size     = New-Object System.Drawing.Size(10, 10)
    $d.Location = New-Object System.Drawing.Point((308 + $i * 20), 20)
    $d.BackColor = $clrSub
    $pnlFooter.Controls.Add($d)
    $dots += $d
}

# ---------------------------------------------------------------------------
# Navigation
# ---------------------------------------------------------------------------
$script:page = 0

function Set-Dots {
    for ($i = 0; $i -lt $dots.Count; $i++) {
        $dots[$i].BackColor = if ($i -eq $script:page) { $clrAccent } else { $clrSub }
    }
}

function Set-Preview($imgName) {
    $old = $pic.Image
    if ($imgName) {
        $img = Load-Asset $imgName
        if ($img) {
            $pic.Image        = $img
            $pic.Visible      = $true
            $lblNoPic.Visible = $false
            if ($old) { $old.Dispose() }
            return
        }
    }
    $pic.Image        = $null
    $pic.Visible      = $false
    $lblNoPic.Visible = $true
    if ($old) { $old.Dispose() }
}

function Show-Step($idx) {
    $step = $steps[$idx]
    $key  = $step.Key

    $lblStepNum.Text   = "Step $($idx + 1) of $($steps.Count)"
    $lblStepTitle.Text = $step.Title
    $lblStepDesc.Text  = $step.Desc

    $pnlRadios.Controls.Clear()

    $y = 0
    $optIdx = 0
    foreach ($opt in $step.Opts) {
        $rb = New-Object System.Windows.Forms.RadioButton
        $rb.SetBounds(0, $y, 405, 22)
        $rb.Text      = $opt.Label
        $rb.Font      = $fntBody
        $rb.ForeColor = $clrText
        $rb.BackColor = [System.Drawing.Color]::Transparent
        $rb.Tag       = $opt.Val
        $rb.Checked   = ($opt.Val -eq $choices[$key])

        $detail = New-Object System.Windows.Forms.Label
        $detail.SetBounds(18, $y + 22, 390, 34)
        $detail.Text      = $opt.Detail
        $detail.Font      = $fntSmall
        $detail.ForeColor = $clrSub
        $detail.BackColor = [System.Drawing.Color]::Transparent

        $rbKey  = $key
        $rbImgs = $step.Imgs
        $rbIdx  = $optIdx

        $rb.Add_CheckedChanged({
            if ($this.Checked) {
                $choices[$rbKey] = $this.Tag
                if ($rbImgs -and $rbIdx -lt $rbImgs.Count) {
                    Set-Preview $rbImgs[$rbIdx]
                }
            }
        }.GetNewClosure())

        $pnlRadios.Controls.Add($rb)
        $pnlRadios.Controls.Add($detail)
        $y += 72
        $optIdx++
    }

    if ($step.Imgs) {
        $selIdx = 0
        for ($i = 0; $i -lt $step.Opts.Count; $i++) {
            if ($step.Opts[$i].Val -eq $choices[$key]) { $selIdx = $i; break }
        }
        Set-Preview $step.Imgs[$selIdx]
    } else {
        Set-Preview $null
    }

    $pnlLeft.Visible    = $true
    $pnlRight.Visible   = $true
    $pnlConfirm.Visible = $false
    $btnNext.Visible    = $true
    $btnInstall.Visible = $false
    Set-Dots
}

function Show-Confirm {
    $lblStepNum.Text = "Step 5 of 5"

    $artLabel  = if ($choices.Artwork     -eq "colorful") { "Colorful"              } else { "Standard (desaturated)" }
    $langLabel = switch ($choices.Language) { "chinese" {"Chinese"} "korean" {"Korean"} default {"Latin + Japanese"} }
    $dofGpLbl  = if ($choices.DofGameplay -eq "disable") { "Disabled"              } else { "Keep HD Depth of Field" }
    $dofCsLbl  = if ($choices.DofCutscene -eq "disable") { "Disabled"              } else { "Keep HD Depth of Field" }

    $lblConfirmBody.Text = @"
  Artwork style          :  $artLabel
  Language               :  $langLabel
  DoF - Gameplay         :  $dofGpLbl
  DoF - Cutscenes        :  $dofCsLbl


Click Install to apply your choices and prepare the mod files.
Nova Chrysalia Launcher will complete the installation afterwards.
"@

    $pnlLeft.Visible    = $false
    $pnlRight.Visible   = $false
    $pnlConfirm.Visible = $true
    $btnNext.Visible    = $false
    $btnInstall.Visible = $true
    Set-Dots
}

function Navigate($delta) {
    $next = $script:page + $delta
    if ($next -lt 0) { return }
    if ($next -ge $steps.Count) {
        $script:page = $steps.Count
        Show-Confirm
        return
    }
    $script:page = $next
    Show-Step $script:page
}

# ---------------------------------------------------------------------------
# Install
# ---------------------------------------------------------------------------
function Run-Install {
    $btnInstall.Enabled = $false
    $btnBack.Enabled    = $false
    $lblConfirmBody.Text = "Applying your choices, please wait..."
    [System.Windows.Forms.Application]::DoEvents()

    # Remove any leftover mod files from a previous manual installation.
    # Nova backs up files it installs itself, but a manual install leaves orphans
    # that would persist after uninstall. We clean them up before Nova touches anything.
    if ($gameBinDir -and [System.IO.Directory]::Exists($gameBinDir)) {
        $lblConfirmBody.Text = "Checking for previous installation..."
        [System.Windows.Forms.Application]::DoEvents()
        foreach ($item in @("version.dll", "hd_textures", "hd_textures_shaders")) {
            $target = [System.IO.Path]::Combine($gameBinDir, $item)
            if (Test-Path -LiteralPath $target) {
                Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    # Ensure destination exists (launcher may create Data\ but not the full subtree)
    if (-not [System.IO.Directory]::Exists($dataDir)) {
        $null = New-Item -ItemType Directory -Force -Path $dataDir
    }

    function Overlay($sub) {
        $s = Join-Path $sourceDir $sub
        if ([System.IO.Directory]::Exists($s)) {
            $null = robocopy $s $dataDir /E /NFL /NDL /NJH /NJS /NP
        } else {
            [System.Windows.Forms.MessageBox]::Show(
                "Warning: source folder not found:`n$s",
                "FF XIII-2 HD Mod", "OK", "Warning")
        }
    }

    # Always copy the base mod first
    Overlay "base"

    if ($choices.Artwork     -eq "colorful") { Overlay "colorful"        }
    if ($choices.Language    -eq "chinese")  { Overlay "fonts_chinese"   }
    if ($choices.Language    -eq "korean")   { Overlay "fonts_korean"    }
    if ($choices.DofGameplay -eq "disable")  { Overlay "nodof_gameplay"  }
    if ($choices.DofCutscene -eq "disable")  { Overlay "nodof_cutscenes" }

    $artLabel  = if ($choices.Artwork     -eq "colorful") { "Colorful"              } else { "Standard" }
    $langLabel = switch ($choices.Language) { "chinese" {"Chinese"} "korean" {"Korean"} default {"Latin + Japanese"} }
    $dofGpLbl  = if ($choices.DofGameplay -eq "disable") { "Disabled"              } else { "HD DoF" }
    $dofCsLbl  = if ($choices.DofCutscene -eq "disable") { "Disabled"              } else { "HD DoF" }

    $lblConfirmBody.Text = @"
Installation complete!

  Artwork      :  $artLabel
  Language     :  $langLabel
  DoF Gameplay :  $dofGpLbl
  DoF Cutscene :  $dofCsLbl

You can now close this window.
Nova Chrysalia Launcher will continue the installation.
"@
    $lblConfirmHdr.Text = "Done"
    $btnInstall.Text    = "Close"
    $btnInstall.Enabled = $true
    $btnInstall.Add_Click({ $form.Close() })
}

# ---------------------------------------------------------------------------
# Wire up and launch
# ---------------------------------------------------------------------------
$btnBack.Add_Click(   { Navigate -1 })
$btnNext.Add_Click(   { Navigate  1 })
$btnInstall.Add_Click({ Run-Install  })

Show-Step 0
[System.Windows.Forms.Application]::Run($form)
